# Generated by Phase: IMPLEMENT | Feature: EVOL-081
"""CI-only delivery (EVOL-081): `gate.py delivery` — the one executor and the one reader of the deployment record.

config    `config/quality.json → delivery`: `execution` (ci | local, derived from ci_cd.platform), `adapter` (the chosen
          deploy-tool row: validate, plan, apply, destroy, url_from, secrets — vault NAMES only), `migrate` (the
          migrations tool's deploy command or null), `secrets` (the vault names the steps need beyond the row),
          `probe` {timeout_s, interval_s}.
--run --env E   validate → plan → migrate (trace: the migration files changed since E's last record, data.py's layout
          scan) → apply → probe every `healthCheckPath` of config/system_resources.json against the URL of `url_from`
          → the deployed measurement (performance, not written) → the record tag → the lkg tag. Any red → exit 1;
          the record is still written once apply ran (it says what is down), the lkg never. With `execution: ci` it
          refuses outside the pipeline (no `CI`); with `local` it runs on the agent's machine, same steps, same tags.
--rollback --env E   HEAD must be the last `lkg/E/*` SHA (the pipeline checks it out), then `--run`: its record is the re-seal.
--teardown --env E   the adapter's `destroy`; null destroy fails closed; writes no tag.
--last E / --lkg E   the latest record / the latest good record, JSON.
--pr --base B --branch NAME   the verdicts the PR pipeline demands of the agent: the preventive sweep (COMPLETED,
          every scope delivered) and the smoke at `qa.smoke_cadence` (APPROVED), each in the PR's diff — owed for a
          `feature/*` branch that is not a sub-increment, the full-sdlc preset, not documentation only (n/a otherwise).
          Their currency is `gate.py currency`'s.
--check   (light profile member) the pipeline file(s): every deploy / teardown stage calls this executor and names
          its environment, production behind approval (GitHub `environment: production`; Bitbucket
          `deployment: production` + `trigger: manual`); every tag push names its own environment; the adapter row
          has `apply` and `url_from`; `execution` is the derivation of ci_cd.platform (None → local, else ci).
          RED when the platform deploys from CI and its pipeline (PIPELINE_FILE) does not call the executor — a shipped
          template on GitHub Actions / Bitbucket Pipelines, one the AI Factory authors at SETUP on every other Q21
          platform (EVOL-081 RDR 9); there the approval is the platform's own, not read here.
          n/a with `execution: local`, no block, or no adapter row, deploy tool or hosting provider answered — no server, nothing deploys (RDR 7).
record    annotated tag `deploy/{env}/{YYYYMMDDTHHMMSSZ}` on the deployed SHA, message = JSON {env, sha, at, adapter,
          probe, migrations, metrics, hosting[, rebaseline]}; `lkg/{env}/{ts}` lightweight on the same SHA. This module
          creates tags only; PUSHING them is the pipeline's step (or the DEVOPS agent's, in local mode) — never here.
Commands from the adapter row run without a shell: ` && ` splits steps, leading `NAME=value` words set the step's
environment, `{env}` is the environment name, `{param}` the row's `params` — a string holds for every environment (it may
name `{env}`), a map {env: value} per environment — and `$NAME` / `${NAME}` the step environment's value (an unset name is a
fault, never an empty word). Every plan / apply / destroy and a url_from template names its environment — `{env}`, or a
per-environment param holding a value of its own per environment — or the row is red (RDR 6): a staging deploy never reaches production. A param
value is one identifier, host or URL. One function (`fill`) fills every command and the url template; every one the run needs is filled before its first step runs: one left unfilled runs nothing. Secrets: only the row's names and `delivery.secrets`, from the environment
or the pipeline's `DELIVERY_SECRETS` JSON map, reach the commands; the map itself never does.
"""
from __future__ import annotations

import datetime as _dt
import json
import os
import re
import shlex
import subprocess
import time
from pathlib import Path

from .common import GateFault, clean, context, key, parse_yaml, tracked_files

TS = "%Y%m%dT%H%M%SZ"
AT = "%Y-%m-%dT%H:%M:%SZ"
ENV_RE = re.compile(r"[a-z][a-z0-9-]{0,30}")
SHA_RE = re.compile(r"[0-9a-f]{40}")
VAR_RE = re.compile(r"\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))")
ASSIGN = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")
URL_KINDS = ("command", "stdout", "template")
ENV_BOUND = ("plan", "apply", "destroy")
PH = r"(?<!\$)\{%s\}"
PLACE = re.compile(PH % r"([A-Za-z_][A-Za-z0-9_-]*)")
PARAM_OK = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:/@%+=,{}-]*")   # an identifier, a host, a URL — never an option, words, quotes or $NAME
USERINFO = re.compile(r"(?:^|//)[^/@]*:[^/@]*@")   # user:password@ — a credential, never a param
REFUSED = "This project deploys from its pipeline — run DEVOPS --deploy, which starts the pipeline and watches the run."
RESOURCES = "config/system_resources.json"
PIPELINE_FILE = {"GitHub Actions": ".github/workflows/deploy.yml", "Bitbucket Pipelines": "bitbucket-pipelines.yml",
                 "GitLab CI": ".gitlab/deploy.yml", "Azure DevOps": "deploy-pipeline.yml", "Jenkins": "Jenkinsfile.deploy",
                 "AWS CodePipeline": "buildspec-deploy.yml", "GCP Cloud Build": "cloudbuild-deploy.yaml"}
COVERED = ("GitHub Actions", "Bitbucket Pipelines")   # a shipped template; every other platform's pipeline is authored (RDR 9)
ALL_ENVS_PUSH = re.compile(r"refs/tags/(deploy|lkg)/\*")


class Refused(GateFault):
    """The executor ran where it must not (exit 1, plain message)."""


# ─── config ────────────────────────────────────────────────────────────────────

def cfg(repo: Path) -> dict | None:
    c = key(repo, "delivery")
    if c is not None and not isinstance(c, dict):
        raise GateFault("`delivery` in config/quality.json is not an object")
    return c


def execution(c: dict | None) -> str:
    v = (c or {}).get("execution", "local")
    if v not in ("ci", "local"):
        raise GateFault(f"`delivery.execution` must be ci or local, not {v!r} — SETUP --upgrade derives it")
    return v


def deploys(repo: Path) -> bool:
    """The one predicate (RDR 7): the project deploys — an adapter row, a deploy tool or a hosting provider answered (no
    server = Q20 unanswered). Without it nothing deploys: `--check` is n/a, `scm-protection` asks no production
    environment and no tag ruleset. An unreadable block or answer home reads as deploying: the checks stay on."""
    from . import data
    try:
        c, ans = cfg(repo) or {}, data.answers(repo)
    except GateFault:
        return True
    told = lambda k: str(ans.get(k) or "").strip() not in ("", "None")
    return c.get("adapter") is not None or told("hosting.deploy_tool") or told("hosting.provider")


def adapter_problems(a) -> list[str]:
    if not isinstance(a, dict):
        return ["`delivery.adapter` is null — no deploy tool chosen (SETUP Q20.1)"]
    out = []
    if str(a.get("tool", "")).strip() in ("", "Other"):
        out.append("the deploy tool is `Other` — declare the project's adapter row (discovery poses the RDR); nothing deploys until then")
    if not isinstance(a.get("apply"), str) or not a["apply"].strip():
        out.append("the adapter row has no `apply` command")
    u = a.get("url_from")
    if not isinstance(u, dict) or u.get("kind") not in URL_KINDS:
        out.append(f"the adapter row has no `url_from` ({' | '.join(URL_KINDS)}) — a deploy whose URL is unknown cannot be probed")
    par = a.get("params") if isinstance(a.get("params"), dict) else {}
    cmds = [(k, a.get(k)) for k in ENV_BOUND] + ([("url_from.template", u.get("template"))] if isinstance(u, dict) and u.get("kind") == "template" else [])
    for k, cmd in cmds:
        if isinstance(cmd, str) and cmd.strip() and not _env_bound(cmd, par):
            out.append(f"`{k}` does not name the environment — a staging deploy could reach production; name {{env}} or a per-environment param")
    for k, v in par.items():
        if k == "env":
            out.append("`params.env` is the environment's own name — the executor fills {env}; rename the param")
            continue
        seen = {}
        for e, x in (v.items() if isinstance(v, dict) else [("every environment", v)]):
            if x is None:
                continue
            if not isinstance(x, str) or not PARAM_OK.fullmatch(x) or USERINFO.search(x):
                out.append(f"`params.{k}` for {e} is {clean(repr(x), 40)} — a param is one identifier, host or URL (no option, spaces, quotes, $NAME or user:password@); a secret goes in `delivery.secrets`")
                continue
            if isinstance(v, dict) and x in seen:
                out.append(f"`params.{k}` holds one value for {seen[x]} and {e} — one environment would deploy over the other")
            seen.setdefault(x, e)
    return out


def _env_bound(cmd: str, par: dict) -> bool:
    """The command names its environment: `{env}`, a per-environment param, or a shared param whose value names `{env}`."""
    for name in PLACE.findall(cmd):
        v = par.get(name)
        if name == "env" or isinstance(v, dict) or (isinstance(v, str) and re.search(PH % "env", v)):
            return True
    return False


def fill(text: str, params, env: str) -> str:
    """The one filling of a row's text for one environment: `{env}`, and each `{param}` — whose value may name `{env}`,
    never another param. A placeholder left over is a fault: nothing runs, nothing is probed."""
    vals = {**_params(params, env), "env": env}
    out = PLACE.sub(lambda m: re.sub(PH % "env", lambda _m: env, vals[m.group(1)]) if m.group(1) in vals else m.group(0), text)
    left = PLACE.findall(out)
    if left:
        raise GateFault(f"the adapter row names {', '.join('{' + x + '}' for x in left)} and its `params` does not fill it for {env} — DEVOPS --configure fills it")
    return out


def _params(params, env: str) -> dict:
    """The row's params for one environment: a string for every environment, a map's own entry; null stays a placeholder."""
    out = {}
    for k, v in (params or {}).items():
        v = v.get(env) if isinstance(v, dict) else v
        if isinstance(v, str) and v.strip():   # a null param stays a placeholder: refused, never run as "None"
            out[k] = v
    return out


def _env_name(env: str) -> str:
    if not ENV_RE.fullmatch(env or ""):
        raise GateFault(f"--env {env!r} is not an environment name (lowercase letters, digits, dashes)")
    return env


def _guard(c: dict | None, environ) -> None:
    if execution(c) == "ci" and not environ.get("CI"):
        raise Refused(REFUSED)


# ─── git ───────────────────────────────────────────────────────────────────────

def _git(repo: Path, *args, check: bool = True) -> str:
    r = subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, timeout=60)
    if check and r.returncode != 0:
        raise GateFault(f"git {args[0]} failed: {clean(r.stderr.strip().splitlines()[-1] if r.stderr.strip() else '', 200)}")
    return r.stdout


def _order(name: str) -> tuple:
    ts = name.rsplit("/", 1)[-1]
    base, _, n = ts.partition("-")
    return (base, int(n) if n.isdigit() else 0)


def records(repo: Path, env: str | None = None, rejected: list | None = None) -> list[dict]:
    """Every deploy record (oldest first), each {tag, env, sha, at, ...}. A tag in the namespace that is no record
    (no JSON body, another environment, no 40-hex sha) is skipped: a planted tag never stops a deploy, never is one.
    `rejected`, when given, receives (tag, why) per skipped tag — the light check reports them, the deploy never reads them."""
    out = []
    for name in sorted(filter(None, _git(repo, "tag", "-l", "deploy/*").splitlines()), key=_order):
        parts = name.split("/")
        if len(parts) != 3 or (env and parts[1] != env):
            continue
        raw = _git(repo, "cat-file", "tag", name, check=False)
        body = raw.split("\n\n", 1)[1] if "\n\n" in raw else ""
        body = body.split("-----BEGIN", 1)[0].strip()
        try:
            rec = json.loads(body)
        except ValueError:
            rec = None
        why = ("no JSON record in its message" if not isinstance(rec, dict)
               else f"its `env` is not {parts[1]}" if rec.get("env") != parts[1]
               else "its `sha` is not a 40-hex commit" if not SHA_RE.fullmatch(str(rec.get("sha", ""))) else None)
        if why:
            if rejected is not None:
                rejected.append((name, why))
            continue
        out.append({"tag": name, **rec})
    return out


def last(repo: Path, env: str) -> dict | None:
    r = records(repo, _env_name(env))
    return r[-1] if r else None


def lkg(repo: Path, env: str) -> dict | None:
    """The newest `lkg/E/*` tag whose own record exists and names the same SHA — a lone or moved lkg tag is no lkg."""
    _env_name(env)
    recs = {r["tag"]: r for r in records(repo, env)}
    for name in reversed(sorted(filter(None, _git(repo, "tag", "-l", f"lkg/{env}/*").splitlines()), key=_order)):
        rec = recs.get(f"deploy/{env}/{name.rsplit('/', 1)[-1]}")
        sha = _git(repo, "rev-list", "-n", "1", name, check=False).strip()
        if rec and rec["sha"] == sha:
            return {**rec, "lkg": name}
    return None


def write_record(repo: Path, env: str, sha: str, payload: dict, good: bool, now: _dt.datetime | None = None) -> str:
    """The record tag (and the lkg tag when good); returns the record tag name. A same-second collision gets `-N`."""
    now = now or _dt.datetime.now(_dt.timezone.utc)
    ts = now.strftime(TS)
    existing = set(_git(repo, "tag", "-l", f"deploy/{env}/{ts}*").splitlines())
    n, name = 0, f"deploy/{env}/{ts}"
    while name in existing:
        n += 1
        name = f"deploy/{env}/{ts}-{n}"
    rec = {"env": env, "sha": sha, "at": now.strftime(AT), **payload}
    ident = [] if _git(repo, "config", "user.email", check=False).strip() else ["-c", "user.name=delivery", "-c", "user.email=delivery@localhost"]
    r = subprocess.run(["git", "-C", str(repo), *ident, "tag", "-a", name, sha, "-m", json.dumps(rec, sort_keys=True)],
                       capture_output=True, text=True, timeout=60)
    if r.returncode != 0:
        raise GateFault(f"the record tag {name} cannot be written — {clean(r.stderr.strip(), 200)}")
    if good:
        _git(repo, "tag", name.replace("deploy/", "lkg/", 1), sha)
    return name


# ─── running the adapter row ───────────────────────────────────────────────────

def _expand(word: str, scope: dict) -> str:
    def val(m):
        name = m.group(1) or m.group(2)
        if not isinstance(scope.get(name), str):
            raise GateFault(f"the adapter command reads ${name} and no declared secret or step variable holds it — name it in `delivery.secrets`")
        return scope[name]
    return VAR_RE.sub(val, word)


def steps(cmd: str, env: str, params: dict | None = None, environ: dict | None = None) -> list[tuple[dict, list[str]]]:
    """A row command → [(assignments, argv)] with no shell: ` && ` separates steps, leading NAME=value words assign;
    `{env}` and each `{param}` of the row's `params` are filled — a placeholder left over is a fault, never run.
    With `environ`, `$NAME` / `${NAME}` in a word is that variable's value (the step's assignments first)."""
    out = []
    cmd = fill(cmd, params, env)
    for part in cmd.split(" && "):
        words = shlex.split(part)
        assign = {}
        while words and ASSIGN.match(words[0]):
            k, v = words.pop(0).split("=", 1)
            assign[k] = _expand(v, {**environ, **assign}) if environ is not None else v
        if environ is not None:
            words = [_expand(w, {**environ, **assign, "DEPLOY_ENV": env}) for w in words]
        if not words:
            raise GateFault(f"the adapter command `{clean(cmd, 80)}` has an empty step")
        out.append((assign, words))
    return out


def _environ(adapter: dict, environ, extra=None) -> dict:
    """The steps' environment: the job's, minus the map, plus the row's secret names and `delivery.secrets` (the names
    the deploy steps need beyond the row — the migration's database URL, the app's config). Nothing else of the map."""
    base = {k: v for k, v in environ.items() if k != "DELIVERY_SECRETS"}
    try:
        vault = json.loads(environ.get("DELIVERY_SECRETS") or "{}")
    except ValueError:
        raise GateFault("DELIVERY_SECRETS is not a JSON map — the pipeline passes it as toJSON(secrets)") from None
    for name in [*(adapter.get("secrets") or []), *(extra if isinstance(extra, list) else [])]:
        if isinstance(vault, dict) and isinstance(vault.get(name), str) and name not in base:
            base[name] = vault[name]
    return base


def run_cmd(repo: Path, cmd: str, env: str, environ: dict, runner=subprocess.run, label: str = "", params: dict | None = None) -> str:
    """Run a row command step by step; its stdout; GateFault naming the step that failed."""
    out = []
    for assign, argv in steps(cmd, env, params, environ):
        try:
            r = runner(argv, cwd=str(repo), env={**environ, **assign, "DEPLOY_ENV": env}, capture_output=True, text=True, timeout=3600)
        except (OSError, subprocess.TimeoutExpired) as e:
            raise GateFault(f"{label or argv[0]}: `{argv[0]}` could not run ({type(e).__name__}) — is the tool installed where the deploy runs?") from None
        out.append(r.stdout or "")
        if r.returncode != 0:
            tail = (r.stderr or r.stdout or "").strip().splitlines()[-1:] or ["(no output)"]
            raise GateFault(f"{label or argv[0]} failed (exit {r.returncode}): {clean(tail[0], 200)}")
    return "".join(out)


def migrations(repo: Path, since: str | None) -> list[str]:
    from . import data
    layouts, tests = data._globs(repo)
    if since and SHA_RE.fullmatch(since):
        r = subprocess.run(["git", "-C", str(repo), "diff", "--name-only", f"{since}..HEAD"], capture_output=True, text=True, timeout=60)
        files = r.stdout.splitlines() if r.returncode == 0 else tracked_files(repo)
    else:
        files = tracked_files(repo)
    return sorted(f for f in files if data.is_migration(f, layouts, tests))


def services(repo: Path) -> list[tuple[str, str]]:
    """(id, healthCheckPath) of every own service in config/system_resources.json; none → the root path."""
    p = repo / RESOURCES
    try:
        doc = json.loads(p.read_text(encoding="utf-8")) if p.is_file() else {}
    except (OSError, ValueError):
        raise GateFault(f"{RESOURCES} is not readable JSON — the probe reads its health paths") from None
    out = [(str(r.get("id")), r["config"]["healthCheckPath"]) for r in doc.get("resources", []) if isinstance(r, dict)
           and r.get("type") != "integration" and isinstance(r.get("config"), dict) and isinstance(r["config"].get("healthCheckPath"), str)]
    return out or [("app", "/")]


def url_of(repo: Path, adapter: dict, apply_out: str, env: str, environ: dict, runner) -> str:
    from .performance import check_url
    u = adapter["url_from"]
    if u["kind"] == "command":
        url = run_cmd(repo, u["command"], env, environ, runner, "url_from", adapter.get("params")).strip()
    elif u["kind"] == "stdout":
        url = ([ln for ln in apply_out.splitlines() if ln.strip()] or [""])[-1]
    elif u["kind"] == "template":
        url = fill(str(u.get("template") or ""), adapter.get("params"), env)
    return check_url(url.strip())


def probe(url: str, svc: list[tuple[str, str]], timeout: float, interval: float) -> dict:
    from .performance import _get
    out = {}
    for sid, path in svc:
        deadline, out[sid] = time.monotonic() + timeout, "down"
        while True:
            try:
                _get(url.rstrip("/") + "/" + path.lstrip("/"), min(30.0, timeout))
                out[sid] = "up"
                break
            except GateFault:
                if time.monotonic() >= deadline:
                    break
                time.sleep(interval)
    return out


def _row(id_, problems, note=""):
    return {"id": id_, "ok": not problems, "problems": problems, "note": note}


def _preflight(a: dict, c: dict, env: str, e: dict) -> None:
    """Fill every command the run will run before its first step: one unfilled placeholder or unset `$NAME` runs nothing."""
    cmds = [a.get(k) for k in ("validate", "plan", "apply")] + [c.get("migrate")]
    u = a.get("url_from") if isinstance(a.get("url_from"), dict) else {}
    if u.get("kind") == "command":
        cmds.append(u.get("command"))
    if u.get("kind") == "template" and isinstance(u.get("template"), str):
        fill(u["template"], a.get("params"), env)
    for cmd in cmds:
        if isinstance(cmd, str) and cmd.strip():
            steps(cmd, env, a.get("params"), e)


def run(repo: Path, env: str, environ=None, runner=subprocess.run, now=None, migrate: bool = True) -> dict:
    environ = os.environ if environ is None else environ
    c = cfg(repo)
    _guard(c, environ)
    env = _env_name(env)
    a = (c or {}).get("adapter")
    bad = adapter_problems(a)
    if bad:
        raise GateFault("; ".join(bad))
    e = _environ(a, environ, (c or {}).get("secrets"))
    _preflight(a, c or {}, env, e)
    sha = _git(repo, "rev-parse", "HEAD").strip()
    rows = []
    if a.get("iac") and (repo / "scripts/validate-iac.sh").is_file():
        run_cmd(repo, "bash scripts/validate-iac.sh", env, e, runner, "IaC coherence"); rows.append(_row("iac", [], "scripts/validate-iac.sh"))
    for step in ("validate", "plan"):
        if a.get(step):
            run_cmd(repo, a[step], env, e, runner, step, a.get("params")); rows.append(_row(step, [], a[step]))
    prev = last(repo, env)
    trace = migrations(repo, prev["sha"] if prev else None)
    if (c or {}).get("migrate") and migrate:
        run_cmd(repo, c["migrate"], env, e, runner, "migrate", a.get("params"))
    rows.append(_row("migrate", [], f"{len(trace)} migration file(s) since {prev['sha'][:8] if prev else 'the first deploy'}"
                     + ("" if migrate else " — not run: a rollback never re-runs the forward migration")))
    out = run_cmd(repo, a["apply"], env, e, runner, "apply", a.get("params"))
    rows.append(_row("apply", [], a["apply"]))
    try:
        url = url_of(repo, a, out, env, e, runner)
    except GateFault as err:
        url, probes = None, {}
        rows.append(_row("url", [str(err)]))
    else:
        pr = (c or {}).get("probe") or {}
        probes = probe(url, services(repo), float(pr.get("timeout_s", 120)), float(pr.get("interval_s", 5)))
        down = [s for s, v in probes.items() if v != "up"]
        rows.append(_row("probe", [f"{s} is down — the deploy reports success while the service does not start (DC-44)" for s in down], f"{len(probes)} service(s) up at {url}"))
    metrics, extra = None, {}
    if url and all(v == "up" for v in probes.values()):
        from . import performance
        try:
            res = performance.measure(repo, env, url, sha=sha, write=False)
        except GateFault as err:
            res = {"ok": False, "na": False, "entries": [], "reason": str(err)}
        if not res.get("na"):
            rows.append(_row("performance", [] if res["ok"] else [res["reason"]] + [p for r in res["entries"] for p in r["problems"]], res["reason"]))
            line = res.get("line")
            if line:
                metrics, extra = line["metrics"], {k: line[k] for k in ("hosting", "rebaseline") if k in line}
    red = [r for r in rows if not r["ok"]]
    tag = write_record(repo, env, sha, {"adapter": a.get("tool"), "probe": probes, "migrations": trace, "metrics": metrics, **extra}, good=not red, now=now)
    rows.append(_row("record", [], tag + ("" if red else f"; {tag.replace('deploy/', 'lkg/', 1)}")))
    return {"ok": not red, "entries": rows, "tag": tag, "reason": (f"{len(red)} red — no lkg tag; {tag} records what is down" if red else f"{env} deployed at {sha[:8]}, sealed {tag}")}


def rollback(repo: Path, env: str, environ=None, runner=subprocess.run, now=None) -> dict:
    environ = os.environ if environ is None else environ
    _guard(cfg(repo), environ)
    good = lkg(repo, env)
    if good is None:
        raise GateFault(f"no last-known-good deploy of {env} (no lkg/{env}/* tag) — nothing to roll back to")
    head = _git(repo, "rev-parse", "HEAD").strip()
    if head != good["sha"]:
        raise GateFault(f"a rollback deploys {good['lkg']} ({good['sha'][:8]}) — check that commit out first, HEAD is {head[:8]}")
    _on_main(repo, good)
    return run(repo, env, environ, runner, now, migrate=False)


def _on_main(repo: Path, good: dict) -> None:
    """RDR 10: a rollback target is a commit of the main branch. Creating a tag stays open, so a well-formed record pair
    on any commit is possible; one no merge produced is never deployed. Nothing runs when it is not on main."""
    from .branch import default_base
    b = default_base(repo)
    if _git(repo, "rev-parse", "--is-shallow-repository", check=False).strip() == "true":
        _git(repo, "fetch", "--quiet", "--unshallow", "origin", b, check=False)
    _git(repo, "fetch", "--quiet", "origin", b, check=False)
    r = subprocess.run(["git", "-C", str(repo), "merge-base", "--is-ancestor", good["sha"], f"origin/{b}"], capture_output=True, text=True, timeout=60)
    if r.returncode == 1:
        raise GateFault(f"{good['lkg']} names {good['sha'][:8]}, which is not on origin/{b} — a record no merge produced is never rolled back to; nothing ran")
    if r.returncode != 0:
        raise GateFault(f"origin/{b} cannot be read, so the rollback target cannot be checked against the main branch — fetch it; nothing ran")


def teardown(repo: Path, env: str, environ=None, runner=subprocess.run) -> dict:
    environ = os.environ if environ is None else environ
    c = cfg(repo)
    _guard(c, environ)
    env = _env_name(env)
    a = (c or {}).get("adapter")
    if not isinstance(a, dict) or not isinstance(a.get("destroy"), str) or not a["destroy"].strip():
        raise GateFault("the deploy tool has no `destroy` command in its adapter row — tear the environment down with the host's own console; nothing was run")
    bad = adapter_problems(a)
    if bad:
        raise GateFault("; ".join(bad) + " — nothing was torn down")
    e = _environ(a, environ, (c or {}).get("secrets"))
    steps(a["destroy"], env, a.get("params"), e)
    run_cmd(repo, a["destroy"], env, e, runner, "destroy", a.get("params"))
    return {"ok": True, "entries": [_row("destroy", [], a["destroy"])], "reason": f"{env} torn down; no record written"}


# ─── the static check (light member) ───────────────────────────────────────────

CALL = re.compile(r"gate\.py\s+delivery\s+--(run|rollback|teardown)\b[^\n]*?--env[ =]\"?([^\s\"]+)")


def _github(doc: dict, rel: str) -> list[str]:
    out = []
    jobs = doc.get("jobs") if isinstance(doc, dict) else None
    for name, job in (jobs or {}).items():
        if not isinstance(job, dict):
            continue
        calls = []
        for st in job.get("steps") or []:
            if not isinstance(st, dict):
                continue
            scope = {**(job.get("env") or {}), **(st.get("env") or {})} if isinstance(job.get("env") or {}, dict) and isinstance(st.get("env") or {}, dict) else {}
            for kind, env in CALL.findall(str(st.get("run", ""))):
                var = re.fullmatch(r"\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?", env)
                calls.append((kind, str(scope.get(var.group(1), env)) if var else env))
        for kind, env in calls:
            want = job.get("environment")
            want = want.get("name") if isinstance(want, dict) else want
            if want is None:
                out.append(f"{rel} job `{name}` runs --{kind} with no `environment:` — production would deploy unapproved")
            elif str(want).strip() != env.strip():
                out.append(f"{rel} job `{name}`: `environment: {want}` is not the environment it deploys ({env})")
    return out


def _bb_steps(node):
    if isinstance(node, dict):
        if "step" in node and isinstance(node["step"], dict):
            yield node["step"]
        for v in node.values():
            yield from _bb_steps(v)
    elif isinstance(node, list):
        for v in node:
            yield from _bb_steps(v)


def _bitbucket(doc: dict, rel: str) -> list[str]:
    out = []
    for st in _bb_steps((doc or {}).get("pipelines")):
        text = "\n".join(str(x) for x in st.get("script") or [])
        for kind, env in CALL.findall(text):
            dep = st.get("deployment")
            if dep is None:
                out.append(f"{rel} step «{st.get('name')}» runs --{kind} with no `deployment:`")
            elif str(dep) != env:
                out.append(f"{rel} step «{st.get('name')}»: `deployment: {dep}` is not the environment it deploys ({env})")
            if env == "production" and st.get("trigger") != "manual":
                out.append(f"{rel} step «{st.get('name')}» deploys production without `trigger: manual` — production waits for a person")
    return out


SWEEP_GLOB = "docs/spec/*/review/preventive_sweep_*.md"


def _verdict(repo: Path, rel: str, paths: list[str], status: str, what: str, extra=None) -> dict:
    """One owed verdict artefact: in this PR's diff, at `status` (and `not_delivered: []` for the sweep)."""
    from .common import read_frontmatter
    if rel not in paths or not (repo / rel).is_file():
        return _row(rel, [f"not in this pull request — {what}"])
    fm = read_frontmatter(repo / rel)
    probs = [] if fm.get("status") == status else [f"status is {fm.get('status')!r}, not {status}"]
    for k, v in (extra or {}).items():
        if fm.get(k) != v:
            probs.append(f"`{k}` is not {v!r} — not every scope delivered")
    return _row(rel, probs, f"{status}")


def pr(repo: Path, base: str, branch: str) -> dict:
    """The verdicts the PR pipeline demands of the agent (RDR 1 sweep, RDR 5 smoke, 2026-11-08). Owed for a
    branch of class feature, increment or train (a sub-increment PR into its train owes the light profile), the full-sdlc
    preset, a change that is not documentation only. Then, each in this PR's diff: the newest preventive-sweep report
    COMPLETED with `not_delivered: []`; the smoke at `qa.smoke_cadence` — `per-slice`: the increment's
    `smoke_e2e_report_INC-N.md` APPROVED; the PR that closes the feature (no increment in the branch, or its last
    INC of increment_plan.md) also `smoke_e2e_report.md` APPROVED. Their currency is `gate.py currency`'s."""
    from . import data, seal
    from . import branch as branch_mod
    from .common import glob_match
    from .train import INC_RE as PLAN_INC
    m = branch_mod.INC_RE.match(branch or "")
    cls = branch_mod.branch_class(repo, branch or "-")["class"] if branch else "unknown"
    if cls == "sub-increment":
        return {"ok": True, "na": True, "reason": "a sub-increment PR into its train owes the light profile — the train's PR carries the verdicts", "entries": []}
    if cls not in ("feature", "increment", "train"):
        return {"ok": True, "na": True, "reason": f"{branch or 'this branch'} is not a feature branch ({cls}) — no verdict owed", "entries": []}
    ans = data.answers(repo)
    if ans.get("project_tracking.feature_phases") != "full-sdlc":
        return {"ok": True, "na": True, "reason": "the feature preset is not full-sdlc — no verdict owed", "entries": []}
    if seal.docs_only(repo, base)["ok"]:
        return {"ok": True, "na": True, "reason": "documentation only — no verdict owed", "entries": []}
    paths = seal.diff_paths(repo, base)
    sweeps = sorted(p for p in paths if glob_match(p, SWEEP_GLOB) and (repo / p).is_file())
    if not sweeps:
        return {"ok": False, "entries": [], "reason": f"no preventive-sweep report ({SWEEP_GLOB}) in this pull request — the agent sweeps the change first"}
    rows = [_verdict(repo, sweeps[-1], paths, "COMPLETED", "the agent sweeps the change first", {"not_delivered": []})]
    feature, inc = sweeps[-1].split("/")[2], (m.group("n") if m else None)
    plan = repo / f"docs/spec/{feature}/increment_plan.md"
    last = max((int(h.group(1)) for h in PLAN_INC.finditer(plan.read_text(encoding="utf-8", errors="replace"))), default=0) if plan.is_file() else 0
    smoke = "the agent deploys this branch (DEVOPS --deploy), runs the smoke (QA --verify) and commits its report"
    if ans.get("qa.smoke_cadence") == "per-slice" and inc:
        rows.append(_verdict(repo, f"docs/spec/{feature}/smoke_e2e_report_INC-{inc}.md", paths, "APPROVED", smoke))
    if not inc or int(inc) >= last:
        rows.append(_verdict(repo, f"docs/spec/{feature}/smoke_e2e_report.md", paths, "APPROVED", smoke + " (this PR closes the feature)"))
    red = [r for r in rows if not r["ok"]]
    return {"ok": not red, "entries": rows, "reason": f"{len(red)} of {len(rows)} verdict(s) red" if red else f"{len(rows)} verdict(s) green"}


def _uncommented(text: str, rel: str) -> str:
    """A pipeline's text without its comments — a floor, not a parser: whole-line `#` in YAML; in a Jenkinsfile (Groovy)
    `/* … */` blocks, whole-line and trailing `//`. A commented-out call is no call; `//` in YAML is live text."""
    if rel.endswith("Jenkinsfile.deploy"):
        text = re.sub(r"/\*.*?\*/", " ", text, flags=re.S)
        return "\n".join(re.sub(r"(^|\s)//.*$", "", ln) for ln in text.splitlines())
    return "\n".join(ln for ln in text.splitlines() if not ln.lstrip().startswith("#"))


def check(repo: Path) -> dict:
    if context(repo) == "meta":
        return {"ok": True, "na": True, "reason": "the framework repo deploys nothing", "entries": []}
    c = cfg(repo)
    if c is None:
        return {"ok": True, "na": True, "reason": "no `delivery` block in config/quality.json — SETUP --upgrade adds it (EVOL-081)", "entries": []}
    from . import data
    plat = data.answers(repo).get("ci_cd.platform")
    if isinstance(plat, str) and plat.strip():
        want = "local" if plat.strip() == "None" else "ci"
        if execution(c) != want:
            return {"ok": False, "entries": [_row("delivery.execution", [f"is {execution(c)}, but ci_cd.platform is {plat} — it derives {want} (SETUP --upgrade writes it); a flipped key switches the CI-only controls off"])],
                    "reason": "delivery.execution is not what ci_cd.platform derives"}
    if execution(c) == "local":
        return {"ok": True, "na": True, "reason": "delivery.execution is local — no pipeline deploys", "entries": []}
    if not deploys(repo):
        return {"ok": True, "na": True, "reason": "no server: no hosting provider, no deploy tool answered — nothing deploys", "entries": []}
    body = lambda p: _uncommented((repo / p).read_text(encoding="utf-8", errors="replace"), p)
    calls = lambda p: (repo / p).is_file() and "gate.py delivery" in body(p)
    want_file = PIPELINE_FILE.get(plat.strip()) if isinstance(plat, str) else None
    files = [want_file] if want_file and calls(want_file) else [] if want_file else [p for p in PIPELINE_FILE.values() if calls(p)]
    if not files:
        if want_file:
            how = "SETUP --upgrade lands the deploy pipeline" if plat.strip() in COVERED else "SETUP authors it for this platform (SETUP --upgrade on an installed project)"
            return {"ok": False, "entries": [_row(want_file, [f"{plat} deploys from CI and {want_file} does not call `gate.py delivery --run` — {how}"])],
                    "reason": "the deploy pipeline is missing"}
        return {"ok": True, "na": True, "reason": "no deploy pipeline file and no CI platform answered", "entries": []}
    rows = [_row("delivery.adapter", adapter_problems(c.get("adapter")), str((c.get("adapter") or {}).get("tool")))]
    for rel in files:
        raw = (repo / rel).read_text(encoding="utf-8", errors="replace")
        text = _uncommented(raw, rel)
        shipped = rel in (PIPELINE_FILE[k] for k in COVERED)
        try:
            doc = parse_yaml(raw) if shipped else None
        except Exception as err:   # the mini parser's every failure is one finding, never a crash
            try:
                import yaml  # type: ignore  # noqa: F401
                why = f"not readable YAML ({type(err).__name__})"
            except ImportError:
                why = "cannot be read without PyYAML — install PyYAML where the gates run (the subset parser reads frontmatter, not pipelines)"
            rows.append(_row(rel, [why]))
            continue
        probs = (_github if rel.startswith(".github/") else _bitbucket)(doc, rel) if shipped else []
        apply_cmd = ((c.get("adapter") or {}).get("apply") or "").split(" && ")[-1].strip()
        if apply_cmd and re.search(re.sub(r"\\\{[A-Za-z_](?:[A-Za-z0-9_]|\\-)*\\\}", r"\\S+", re.escape(apply_cmd)), text):   # a placeholder is any filled word
            probs.append(f"{rel} runs the adapter's apply directly — every deploy goes through `gate.py delivery --run` (probe + record)")
        if not CALL.search(text):
            probs.append(f"{rel} has no stage that calls `gate.py delivery --run --env …`")
        if ALL_ENVS_PUSH.search(text):
            probs.append(f"{rel} pushes every environment's tags — each stage pushes only its own (refs/tags/deploy/<env>/*, refs/tags/lkg/<env>/*)")
        rows.append(_row(rel, probs, "every deploy stage calls the executor; production waits for approval" if shipped
                         else "the executor is called, no direct apply, own tags only; production's approval is the platform's own and is not read here"))
    red = [r for r in rows if not r["ok"]]
    return {"ok": not red, "entries": rows, "reason": f"{len(red)} of {len(rows)} red" if red else f"{len(rows)} green"}


def render(res: dict, name: str = "delivery") -> str:
    if not res.get("entries"):
        return clean(f"{name}: {'n/a' if res.get('na') else 'ok' if res['ok'] else 'RED'} — {res['reason']}")
    lines = [f"{name}: {'ok' if res['ok'] else 'RED'} — {res['reason']}"]
    for r in res["entries"]:
        lines += [f"  ✓ {r['id']}: {r['note']}"] if r["ok"] else [f"  ✗ {r['id']}: {p}" for p in r["problems"]]
    return "\n".join(clean(ln) for ln in lines)
